        body: { error: 'Groq request failed', detail: errorText || `HTTP ${response.status}` }
      };
    }
  }

  return {
    ok: false as const,
    status: 400,
    body: {
      error: 'Groq model is decommissioned.',
      detail: 'Update GROQ_MODEL in .env.local to a currently supported model, e.g. llama-3.3-70b-versatile.'
    }
  };
}

